'use client'

import { useRef, useMemo } from 'react'
import { useFrame } from '@react-three/fiber'
import * as THREE from 'three'

function noise3D(x: number, y: number, z: number): number {
  return (
    Math.sin(x * 1.27 + y * 3.41 + z * 2.63) * 0.3 +
    Math.sin(x * 2.91 + y * 1.73 + z * 4.29) * 0.3 +
    Math.sin(x * 4.63 + y * 5.17 + z * 1.51) * 0.2 +
    Math.sin(x * 7.13 + y * 2.37 + z * 6.89) * 0.2
  )
}

function fbm(x: number, y: number, z: number, octaves: number): number {
  let value = 0
  let amplitude = 1
  let frequency = 1
  let total = 0
  for (let i = 0; i < octaves; i++) {
    value += amplitude * noise3D(x * frequency + i * 17.3, y * frequency + i * 31.7, z * frequency + i * 47.1)
    total += amplitude
    amplitude *= 0.45
    frequency *= 2.2
  }
  return value / total
}

// Varied island shapes: 4 large continents + 8 small atolls
interface IslandDef {
  center: [number, number, number]
  size: number
  stretch: [number, number, number]
  type: 'continent' | 'atoll'
}

const ISLANDS: IslandDef[] = (() => {
  const islands: IslandDef[] = []

  // 5 large continents - much bigger sizes for 50/50 coverage
  const continentSeeds = [
    { phi: 0.6, theta: 0.3, size: 0.7, stretch: [1.3, 1.0, 0.8] as [number, number, number] },
    { phi: 1.6, theta: 2.5, size: 0.65, stretch: [0.7, 1.0, 1.4] as [number, number, number] },
    { phi: 1.0, theta: 4.8, size: 0.6, stretch: [1.5, 1.0, 0.9] as [number, number, number] },
    { phi: 2.4, theta: 1.0, size: 0.55, stretch: [1.0, 1.0, 1.6] as [number, number, number] },
    { phi: 2.0, theta: 3.8, size: 0.6, stretch: [1.2, 1.0, 1.2] as [number, number, number] },
  ]

  for (const s of continentSeeds) {
    islands.push({
      center: [
        Math.sin(s.phi) * Math.cos(s.theta),
        Math.cos(s.phi),
        Math.sin(s.phi) * Math.sin(s.theta),
      ],
      size: s.size,
      stretch: s.stretch,
      type: 'continent',
    })
  }

  // 10 medium islands to fill gaps
  const mediumSeeds = [
    { phi: 0.4, theta: 2.0, size: 0.35 },
    { phi: 1.3, theta: 1.2, size: 0.3 },
    { phi: 2.7, theta: 2.3, size: 0.32 },
    { phi: 1.8, theta: 5.5, size: 0.28 },
    { phi: 0.9, theta: 3.5, size: 0.33 },
    { phi: 2.2, theta: 4.8, size: 0.3 },
    { phi: 1.5, theta: 0.8, size: 0.25 },
    { phi: 0.5, theta: 5.0, size: 0.28 },
    { phi: 2.6, theta: 0.5, size: 0.26 },
    { phi: 1.1, theta: 5.8, size: 0.3 },
  ]

  for (const s of mediumSeeds) {
    islands.push({
      center: [
        Math.sin(s.phi) * Math.cos(s.theta),
        Math.cos(s.phi),
        Math.sin(s.phi) * Math.sin(s.theta),
      ],
      size: s.size,
      stretch: [1, 1, 1],
      type: 'atoll',
    })
  }

  return islands
})()

function islandInfluence(nx: number, ny: number, nz: number): { influence: number; nearCoast: boolean } {
  let maxInfluence = -1

  for (let i = 0; i < ISLANDS.length; i++) {
    const island = ISLANDS[i]
    const [cx, cy, cz] = island.center

    // Apply directional stretch
    const dx = (nx - cx) * island.stretch[0]
    const dy = (ny - cy) * island.stretch[1]
    const dz = (nz - cz) * island.stretch[2]
    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz)

    const radius = island.size
    if (dist < radius) {
      const t = 1 - dist / radius
      let influence = t * t * (3 - 2 * t) // smoothstep

      // Jagged coastlines via noise
      const coastNoise = fbm(nx * 10 + i * 13, ny * 10 + i * 27, nz * 10 + i * 41, 4) * 0.35
      influence += coastNoise * t * t

      // Continents get extra interior noise for ridges/plateaus
      if (island.type === 'continent' && influence > 0.3) {
        const ridge = Math.abs(fbm(nx * 18 + i * 5, ny * 18, nz * 18, 3))
        influence += ridge * 0.2
      }

      if (influence > maxInfluence) maxInfluence = influence
    }
  }

  const nearCoast = maxInfluence > 0.05 && maxInfluence < 0.2
  return { influence: maxInfluence, nearCoast }
}

export function Planet() {
  const meshRef = useRef<THREE.Mesh>(null)
  const cloudsRef = useRef<THREE.Mesh>(null)

  useFrame(({ clock }) => {
    if (cloudsRef.current) {
      cloudsRef.current.rotation.y = clock.elapsedTime * 0.03
    }
  })

  const geometry = useMemo(() => {
    const geo = new THREE.IcosahedronGeometry(3.0, 8)
    const positions = geo.attributes.position
    const colors = new Float32Array(positions.count * 3)

    for (let i = 0; i < positions.count; i++) {
      const x = positions.getX(i)
      const y = positions.getY(i)
      const z = positions.getZ(i)

      const len = Math.sqrt(x * x + y * y + z * z)
      const nx = x / len
      const ny = y / len
      const nz = z / len

      const { influence, nearCoast } = islandInfluence(nx, ny, nz)
      const isLand = influence > 0.1

      let height: number
      if (isLand) {
        // Terrain with plateaus and cliffs
        const hills = fbm(nx * 15, ny * 15, nz * 15, 5) * 0.5 + 0.5
        const cliff = Math.pow(influence, 0.6) // steeper edges
        const plateau = influence > 0.5 ? 0.05 : 0 // flat tops on high areas
        height = 3.0 + cliff * 0.22 + hills * influence * 0.1 + plateau
      } else {
        height = 3.0 - 0.04
      }

      positions.setXYZ(i, nx * height, ny * height, nz * height)

      // Vibrant biome colors
      if (isLand) {
        if (nearCoast) {
          // Sandy beach band
          colors[i * 3] = 0.96
          colors[i * 3 + 1] = 0.87
          colors[i * 3 + 2] = 0.52
        } else if (influence > 0.75) {
          // Snow caps
          const snow = fbm(nx * 20, ny * 20, nz * 20, 2) * 0.5 + 0.5
          if (snow > 0.5) {
            colors[i * 3] = 0.95
            colors[i * 3 + 1] = 0.97
            colors[i * 3 + 2] = 1.0
          } else {
            // Exposed rock
            colors[i * 3] = 0.52
            colors[i * 3 + 1] = 0.47
            colors[i * 3 + 2] = 0.42
          }
        } else if (influence > 0.55) {
          // Dark forest at mid-high elevation
          const forestVar = fbm(nx * 30, ny * 30, nz * 30, 2) * 0.5 + 0.5
          colors[i * 3] = 0.1 + forestVar * 0.08
          colors[i * 3 + 1] = 0.35 + forestVar * 0.15
          colors[i * 3 + 2] = 0.08 + forestVar * 0.05
        } else {
          // Lush grassland
          const grassVar = fbm(nx * 25, ny * 25, nz * 25, 2) * 0.5 + 0.5
          colors[i * 3] = 0.18 + grassVar * 0.12
          colors[i * 3 + 1] = 0.55 + grassVar * 0.25
          colors[i * 3 + 2] = 0.1 + grassVar * 0.08
        }
      } else {
        // Ocean depth gradient
        const shallowFactor = Math.max(0, (influence + 0.1)) * 4
        colors[i * 3] = 0.02 + shallowFactor * 0.25
        colors[i * 3 + 1] = 0.12 + shallowFactor * 0.45
        colors[i * 3 + 2] = 0.4 + shallowFactor * 0.35
      }
    }

    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    geo.computeVertexNormals()
    return geo
  }, [])

  // Cloud patches
  const cloudGeo = useMemo(() => {
    const geo = new THREE.IcosahedronGeometry(3.4, 5)
    const positions = geo.attributes.position
    for (let i = 0; i < positions.count; i++) {
      const x = positions.getX(i)
      const y = positions.getY(i)
      const z = positions.getZ(i)
      const len = Math.sqrt(x * x + y * y + z * z)
      positions.setXYZ(i, (x / len) * 3.4, (y / len) * 3.4, (z / len) * 3.4)
    }
    geo.computeVertexNormals()
    return geo
  }, [])

  // Generate tree positions on land
  const treeData = useMemo(() => {
    const trees: { pos: [number, number, number]; scale: number }[] = []
    const count = 300
    for (let i = 0; i < count; i++) {
      const phi = Math.acos(1 - 2 * (i + 0.5) / count)
      const theta = Math.PI * (1 + Math.sqrt(5)) * (i + 0.5)
      const nx = Math.sin(phi) * Math.cos(theta)
      const ny = Math.cos(phi)
      const nz = Math.sin(phi) * Math.sin(theta)

      const { influence } = islandInfluence(nx, ny, nz)
      // Only place on grassy/forest areas
      if (influence < 0.25 || influence > 0.7) continue

      const hills = fbm(nx * 15, ny * 15, nz * 15, 5) * 0.5 + 0.5
      const cliff = Math.pow(influence, 0.6)
      const height = 3.0 + cliff * 0.22 + hills * influence * 0.1

      trees.push({
        pos: [nx * height, ny * height, nz * height],
        scale: 0.025 + noise3D(nx * 50, ny * 50, nz * 50) * 0.5 * 0.02,
      })
    }
    return trees
  }, [])

  return (
    <group>
      {/* Planet terrain */}
      <mesh ref={meshRef} geometry={geometry}>
        <meshLambertMaterial vertexColors flatShading />
      </mesh>

      {/* Water */}
      <AnimatedWater />

      {/* Trees */}
      {treeData.map((tree, i) => (
        <SimpleTree key={i} position={tree.pos} scale={tree.scale} />
      ))}

      {/* Clouds */}
      <mesh ref={cloudsRef} geometry={cloudGeo}>
        <meshBasicMaterial
          color="#ffffff"
          transparent
          opacity={0.12}
          side={THREE.DoubleSide}
          depthWrite={false}
        />
      </mesh>

      {/* Atmosphere rim */}
      <mesh>
        <sphereGeometry args={[3.6, 32, 32]} />
        <meshBasicMaterial
          color="#55aaff"
          transparent
          opacity={0.04}
          side={THREE.BackSide}
        />
      </mesh>
    </group>
  )
}

function SimpleTree({ position, scale }: { position: [number, number, number]; scale: number }) {
  const up = new THREE.Vector3(...position).normalize()
  const quaternion = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), up)

  return (
    <group position={position} quaternion={quaternion} scale={scale}>
      {/* Trunk */}
      <mesh position={[0, 0.3, 0]}>
        <cylinderGeometry args={[0.12, 0.2, 0.6, 4]} />
        <meshLambertMaterial color="#6B4226" flatShading />
      </mesh>
      {/* Canopy */}
      <mesh position={[0, 1.0, 0]}>
        <coneGeometry args={[0.7, 1.0, 5]} />
        <meshLambertMaterial color="#228B22" flatShading />
      </mesh>
      <mesh position={[0, 1.5, 0]}>
        <coneGeometry args={[0.5, 0.8, 5]} />
        <meshLambertMaterial color="#2EA043" flatShading />
      </mesh>
    </group>
  )
}

function AnimatedWater() {
  const ref = useRef<THREE.Mesh>(null)
  const geoRef = useRef<THREE.SphereGeometry | null>(null)

  const geo = useMemo(() => {
    const g = new THREE.SphereGeometry(3.02, 96, 96)
    geoRef.current = g
    return g
  }, [])

  const originalPositions = useMemo(() => {
    return new Float32Array(geo.attributes.position.array)
  }, [geo])

  useFrame(({ clock }) => {
    if (!geoRef.current) return
    const positions = geoRef.current.attributes.position
    const time = clock.elapsedTime

    for (let i = 0; i < positions.count; i++) {
      const ox = originalPositions[i * 3]
      const oy = originalPositions[i * 3 + 1]
      const oz = originalPositions[i * 3 + 2]

      const len = Math.sqrt(ox * ox + oy * oy + oz * oz)
      const nx = ox / len
      const ny = oy / len
      const nz = oz / len

      const wave1 = Math.sin(nx * 8 + time * 1.2) * Math.cos(nz * 6 + time * 0.8) * 0.01
      const wave2 = Math.sin(ny * 12 + time * 1.8 + nx * 4) * 0.006
      const wave3 = Math.sin((nx + nz) * 18 + time * 2.5) * 0.003

      const newLen = 3.02 + wave1 + wave2 + wave3
      positions.setXYZ(i, nx * newLen, ny * newLen, nz * newLen)
    }

    positions.needsUpdate = true
    geoRef.current.computeVertexNormals()
  })

  return (
    <mesh ref={ref} geometry={geo}>
      <meshPhongMaterial
        color="#1e90d4"
        transparent
        opacity={0.5}
        shininess={140}
        specular="#aaeeff"
      />
    </mesh>
  )
}
